/* ================= TOOLS: 5 HUBS ================= */
const HUB = [['analyze', '🔬 Analyze', 'research and signals', ['briefing', 'signals', 'xray', 'confluence', 'score-changes', 'previews', 'congress', 'short-squeeze', 'correlation', 'fairvalue', 'baskets', 'crashtest', 'timemachine', 'sotd', 'investors', 'ask']],
  ['learn', '🎓 Learn', 'grow your skills', ['academy', 'learn', 'letters', 'legend-quiz', 'brokers', 'goal', 'widgets', 'showcase', 'app']],
  ['play', '🎮 Play', 'games and contests', ['tickerdle', 'pick5', 'predict', 'replay-board', 'paper/replay', 'leagues', 'paper', 'options', 'orders']],
  ['track', '📌 Track', 'your money and your lists', ['dashboard', 'alerts', 'calendar', 'portfolio-lab', 'recap', 'account']],
  ['community', '💬 Community', 'people and ideas', ['community', 'feed', 'calls', 'groups', 'creators', 'social', 'members']]];
