    sec.innerHTML = `<div class="r3-hf"><input id="r3-hq" placeholder="Find a tool… (e.g. options, quiz, earnings)" aria-label="Find a tool">${HUB.map(h => `<a href="#r3-${h[0]}" data-j="${h[0]}">${h[1]}</a>`).join('')}</div>`;
    HUB.forEach(h => { const L = tiles.filter(a => !used.has(a) && h[3].some(p => key(a) === p || key(a).startsWith(p + '/'))); L.forEach(a => used.add(a)); if (!L.length) return; const s = document.createElement('div'); s.id = 'r3-' + h[0]; s.innerHTML = `<h2>${h[1]} <small>${h[2]} · ${L.length}</small></h2><div class="tt-g"></div>`; L.forEach(a => $('.tt-g', s).appendChild(a)); sec.appendChild(s); });
