/* ================= CORRELATION MAP ================= */
function correlation() {
  const P = papers(), W = jget('tw-watchlist', []).filter(t => BY[t]), src = [['wl', 'My watchlist']].concat(P.map(p => ['p:' + p.id, 'Paper: ' + (p.name || 'Portfolio')])).concat([['top', 'Top 12 scores']]);
  app.innerHTML = head('Correlation Map', 'Do your stocks all move together? High correlation means you own the same bet several times, so one bad day hits everything at once.') + wrap(card('Pick a List', '', `<form class="r3-f" id="r3-cf"><label>Stocks<select name="s">${opts(src, W.length >= 2 ? 'wl' : 'top')}</select></label></form><div id="r3-co" style="margin-top:14px"></div>`));
  document.title = 'Correlation Map — Tickerwise'; const f = $('#r3-cf');
  const run = () => { let T = []; if (f.s.value === 'wl') T = W; else if (f.s.value === 'top') T = S.slice().sort((a, b) => (b.ws || 0) - (a.ws || 0)).slice(0, 12).map(s => s.t); else { const p = P.find(x => 'p:' + x.id === f.s.value); if (p) T = [...new Set((p.lots || []).filter(l => !l.sd).map(l => l.t))].filter(t => BY[t]); } T = T.slice(0, 16);
    if (T.length < 2) { $('#r3-co').innerHTML = '<p class="muted" style="margin:0">Need at least 2 stocks.</p>'; return; }
    const d1 = lastD(), days = ser('SPY').filter(p => p.d > d1 - 182).map(p => p.d), RT = T.map(t => { const v = days.map(d => (closeOn(t, d) || {}).c); return v.slice(1).map((x, i) => x && v[i] ? Math.log(x / v[i]) : 0); });
    const cor = (a, b) => { const n = a.length, ma = a.reduce((x, y) => x + y, 0) / n, mb = b.reduce((x, y) => x + y, 0) / n; let s = 0, sa = 0, sb = 0; for (let i = 0; i < n; i++) { s += (a[i] - ma) * (b[i] - mb); sa += (a[i] - ma) ** 2; sb += (b[i] - mb) ** 2; } return s / Math.sqrt(sa * sb || 1); };
    const C = T.map((t, i) => T.map((u, j) => i === j ? 1 : cor(RT[i], RT[j]))), pairs = []; T.forEach((t, i) => T.forEach((u, j) => { if (j > i) pairs.push([t, u, C[i][j]]); })); pairs.sort((a, b) => b[2] - a[2]); const avg = pairs.reduce((a, p) => a + p[2], 0) / pairs.length;
    const bg = v => v >= 0 ? `rgba(239,68,68,${Math.max(.05, v)})` : `rgba(16,185,129,${Math.min(.9, -v * 1.5)})`, n = T.length;
    $('#r3-co').innerHTML = `<div class="r3-k"><div><span>Average correlation</span><b>${avg.toFixed(2)}</b></div><div><span>Most alike</span><b style="font-size:16px">${pairs[0][0]} & ${pairs[0][1]} (${pairs[0][2].toFixed(2)})</b></div><div><span>Best diversifiers</span><b style="font-size:16px">${pairs[pairs.length - 1][0]} & ${pairs[pairs.length - 1][1]} (${pairs[pairs.length - 1][2].toFixed(2)})</b></div></div>
      <p style="margin:12px 0">${avg > .6 ? '⚠️ These stocks move very much alike. Diversify across sectors to smooth the ride.' : avg > .35 ? 'Moderately related: some diversification.' : '✓ Well diversified: these stocks often move independently.'}</p>
      <div class="r3-sc"><div class="r3-cm" style="grid-template-columns:52px repeat(${n},minmax(26px,1fr));min-width:${52 + n * 28}px"><div></div>${T.map(t => `<div style="font-size:9.5px">${t}</div>`).join('')}${T.map((t, i) => `<div style="font-size:9.5px;justify-content:start">${t}</div>${C[i].map((v, j) => `<div style="background:${i === j ? '#E2E8F0' : bg(v)}" title="${t} vs ${T[j]}: ${v.toFixed(2)}">${i === j ? '' : v.toFixed(1)}</div>`).join('')}`).join('')}</div></div>
      <p class="muted" style="margin:8px 0 0;font-size:12.5px">Daily returns, last 6 months. 1 = always move together, 0 = unrelated, negative = tend to move opposite. Red = alike, green = diversifying.</p>`; };
  f.onchange = run; run();
}

/* ================= PORTFOLIO LAB ================= */
function lab(pid) {
  const P = papers(); if (!P.length) { app.innerHTML = head('Portfolio Lab', 'Tools for your Paper Trading portfolios.') + wrap('<p>Start a <a href="#/paper">Paper Trading portfolio</a> first.</p>'); return; }
  const p = P.find(x => x.id === pid) || P[0], c = PP.calc ? PP.calc(p) : null; if (!c) return; const open = c.open, tot = c.total, ld = lastD();
  const bmk = [['SPY', 'S&P 500'], ['EQ', 'All Tickerwise stocks (equal weight)']].concat([...new Set(S.map(s => s.sec))].filter(Boolean).slice(0, 12).map(x => ['sec:' + x, x + ' sector']));
  const byT = {}; open.forEach(r => { byT[r.t] = (byT[r.t] || 0) + r.v; }), secW = {}; Object.entries(byT).forEach(([t, v]) => { const s = (BY[t] || {}).sec || 'Other'; secW[s] = (secW[s] || 0) + v; });
  const big = Object.entries(byT).sort((a, b) => b[1] - a[1]), bigS = Object.entries(secW).sort((a, b) => b[1] - a[1]), warn = [];
  if (big[0] && big[0][1] / tot > .25) warn.push(`⚠️ <b>${big[0][0]}</b> is ${(big[0][1] / tot * 100).toFixed(0)}% of the portfolio. Many investors cap one stock at 10–20%.`);
  if (bigS[0] && bigS[0][1] / tot > .45) warn.push(`⚠️ <b>${esc(bigS[0][0])}</b> is ${(bigS[0][1] / tot * 100).toFixed(0)}% of the portfolio: a sector-wide drop would hurt a lot.`);
  if (c.cash / tot > .5) warn.push(`💵 ${(c.cash / tot * 100).toFixed(0)}% is sitting in cash.`); if (big.length && big.length < 5) warn.push(`Only ${big.length} stock${big.length === 1 ? '' : 's'}: one bad report can swing the whole portfolio.`); if (!warn.length) warn.push('✓ No concentration problems found.');
  const closed = c.closed.map(r => { const now = last(r.t); return now ? Object.assign({}, r, { now: now.c, miss: (now.c / r.sp - 1) * 100 }) : null; }).filter(Boolean).sort((a, b) => b.miss - a.miss);
  app.innerHTML = head('Portfolio Lab', 'Benchmarks, rebalancing, sell regret and risk checks for your Paper Trading portfolios.') + wrap(`
    <form class="r3-f"><label>Portfolio<select id="r3-lp">${opts(P.map(x => [x.id, x.name || 'Portfolio']), p.id)}</select></label><label>Benchmark<select id="r3-lb">${opts(bmk, 'SPY')}</select></label></form>
    ${card('Performance vs Benchmark', '', '<div id="r3-lbo"></div>')}
    ${card('Risk Check', '', `<ul style="margin:0;padding-left:18px;line-height:1.7">${warn.map(w => `<li>${w}</li>`).join('')}</ul><div style="display:flex;height:18px;border-radius:9px;overflow:hidden;margin-top:12px">${bigS.map((x, i) => `<i title="${esc(x[0])} ${(x[1] / tot * 100).toFixed(0)}%" style="display:block;width:${x[1] / tot * 100}%;background:${['#2F6BFF', '#00C176', '#F59E0B', '#7C3AED', '#EF4444', '#0EA5E9', '#EC4899', '#64748B'][i % 8]}"></i>`).join('')}<i style="display:block;flex:1;background:#E2E8F0" title="Cash"></i></div><p class="muted" style="margin:6px 0 0;font-size:12.5px">${bigS.map(x => `${esc(x[0])} ${(x[1] / tot * 100).toFixed(0)}%`).join(' · ')} · cash ${(c.cash / tot * 100).toFixed(0)}%</p>`)}
    ${card('Rebalancer', 'set target weights; we suggest the trades', big.length ? `<div class="r3-sc"><table class="r3-t" id="r3-rb"><tr><th>Stock</th><th class="n">Now</th><th class="n">Target %</th><th class="n">Trade</th></tr>${big.map(([t, v]) => `<tr data-t="${t}"><td>${tl(t)}</td><td class="n">${(v / tot * 100).toFixed(1)}%</td><td class="n"><input type="number" min="0" max="100" step="1" value="${(100 / big.length * .97).toFixed(0)}" style="width:70px;padding:6px;border:1.5px solid var(--line);border-radius:8px"></td><td class="n tr">—</td></tr>`).join('')}</table></div><p style="margin:10px 0 0"><button class="btn ghost" id="r3-eq" type="button">Equal weight</button> <button class="btn ghost" id="r3-sw" type="button">Weight by score</button> <button class="btn primary" id="r3-go" type="button">Apply Trades at Last Close</button></p>` : '<p class="muted" style="margin:0">No open positions.</p>')}
    ${card('Sell Regret', 'what your sold stocks did after you sold', closed.length ? `<div class="r3-sc"><table class="r3-t"><tr><th>Stock</th><th class="n">Sold</th><th class="n">Price then</th><th class="n">Now</th><th class="n">Since you sold</th></tr>${closed.slice(0, 15).map(r => `<tr><td>${tl(r.t)}</td><td class="n">${esc(dfmt(r.sd))}</td><td class="n">${usd(r.sp)}</td><td class="n">${usd(r.now)}</td><td class="n ${gcol(-r.miss)}"><b>${pct(r.miss)}</b> ${r.miss > 10 ? '😬' : r.miss < -10 ? '😎' : ''}</td></tr>`).join('')}</table></div><p class="muted" style="margin:8px 0 0;font-size:12.5px">😎 = you sold before a drop. 😬 = it kept rising without you.</p>` : '<p class="muted" style="margin:0">No closed trades yet.</p>')}`);
  document.title = 'Portfolio Lab — Tickerwise';
  $('#r3-lp').onchange = e => { location.hash = '#/portfolio-lab/' + e.target.value; };
  const bench = () => { const k = $('#r3-lb').value, cv = PP.curve ? PP.curve(p) : null, box = $('#r3-lbo'); if (!cv || !cv.length) { box.innerHTML = '<p class="muted" style="margin:0">Not enough history yet.</p>'; return; }
    const pts = cv.map(x => 100 + x[1]), dds = cv.map(x => x[0]);
    const L = k === 'SPY' ? ['SPY'] : k === 'EQ' ? S.map(s => s.t) : S.filter(s => s.sec === k.slice(4)).map(s => s.t), b0 = {}; L.forEach(t => { const c0 = closeOn(t, dds[0]); if (c0) b0[t] = c0.c; }); const ks = Object.keys(b0);
    const bv = dds.map(d => ks.length ? ks.reduce((a, t) => { const c1 = closeOn(t, d); return a + (c1 ? c1.c / b0[t] : 1); }, 0) / ks.length * pts[0] : null), r1 = (pts[pts.length - 1] / pts[0] - 1) * 100, r2 = (bv[bv.length - 1] / bv[0] - 1) * 100;
    box.innerHTML = `<div class="r3-k"><div><span>Your portfolio</span><b class="${gcol(r1)}">${pct(r1)}</b></div><div><span>${esc(($('#r3-lb').selectedOptions[0] || {}).text || '')}</span><b class="${gcol(r2)}">${pct(r2)}</b></div><div><span>You vs benchmark</span><b class="${gcol(r1 - r2)}">${pct(r1 - r2)}</b></div></div><div style="margin-top:10px">${svgLine([{ v: pts, c: '#2F6BFF' }, { v: bv, c: '#94A3B8', dash: 1, w: 2 }])}</div>${legend([['You', '#2F6BFF'], ['Benchmark', '#94A3B8']])}`; };
  $('#r3-lb').onchange = bench; try { bench(); } catch (e) { $('#r3-lbo').innerHTML = '<p class="muted" style="margin:0">Not enough history yet.</p>'; }
  const rb = $('#r3-rb'); if (rb) { const calcT = () => { $$('tr[data-t]', rb).forEach(tr => { const t = tr.dataset.t, w = +$('input', tr).value || 0, cur = byT[t] || 0, tgt = tot * w / 100, px = (last(t) || {}).c, sh = px ? Math.trunc((tgt - cur) / px) : 0; tr.dataset.q = sh; $('.tr', tr).innerHTML = sh ? `<b class="${sh > 0 ? 'up' : 'dn'}">${sh > 0 ? 'Buy' : 'Sell'} ${Math.abs(sh)}</b>` : '—'; }); }; rb.oninput = calcT; calcT();
    $('#r3-eq').onclick = () => { $$('tr[data-t] input', rb).forEach(i => i.value = (97 / big.length).toFixed(0)); calcT(); }; $('#r3-sw').onclick = () => { const ws = big.map(([t]) => (BY[t] || {}).ws || 1), sm = ws.reduce((a, b) => a + b, 0); $$('tr[data-t] input', rb).forEach((i, k) => i.value = (97 * ws[k] / sm).toFixed(0)); calcT(); };
    $('#r3-go').onclick = () => { const o = jget('tw_paper', { prof: null, list: [] }), P2 = o.list.find(x => x.id === p.id), d = iso(ld); let n = 0; $$('tr[data-t]', rb).sort((a, b) => +a.dataset.q - +b.dataset.q).forEach(tr => { const t = tr.dataset.t, qn = +tr.dataset.q, px = +((last(t) || {}).c || 0).toFixed(4); if (!qn || !px) return; n++;
      if (qn > 0) P2.lots.push({ id: uid(), t, q: qn, bd: d, bp: px, sd: null, sp: null }); else { let need = -qn; P2.lots.filter(l => l.t === t && !l.sd).forEach(l => { if (need <= 0) return; if (l.q <= need) { l.sd = d; l.sp = px; need -= l.q; } else { P2.lots.push({ id: uid(), t, q: l.q - need, bd: l.bd, bp: l.bp, sd: null, sp: null }); l.q = need; l.sd = d; l.sp = px; need = 0; } }); } });
      if (PP.calc(P2).cash < -1) { toast('Not enough cash for those targets. Lower the weights.'); return; } jset('tw_paper', o); toast(`✓ ${n} trade${n === 1 ? '' : 's'} placed at the last close`); lab(p.id); }; }
}

/* ================= ONE-PAGE REPORT (print to PDF) ================= */
function report(t) {
  t = (t || '').toUpperCase(); const s = BY[t]; if (!s) { location.hash = '#/'; return; } const r = meter('rp', t); if (!r.ok) { app.innerHTML = head('One-Page Report: ' + esc(t), '') + meterWall(r); return; }
  const P = s.P || {}, l = last(t), A = (TW.AN || {})[t], E = s.earn || {}, own = window.TWFI && window.TWFI.OWN && window.TWFI.OWN[t], W2 = window.TWR2 && window.TWR2.whyMoving ? '' : '';
  const z = ser(t).slice(-252), mn = Math.min(...z.map(p => p.c)), mx = Math.max(...z.map(p => p.c));
  app.innerHTML = `<section class="sec" style="padding-top:22px"><div class="wrap"><p class="r3-noprint" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><button class="btn primary" onclick="window.print()">🖨️ Print or Save as PDF</button> <a class="btn ghost" href="#/stock/${esc(t)}">← Back to ${esc(t)}</a> ${meterBadge(r)}</p>
   <div class="r3-rep"><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:flex-start"><div><h1>${esc(t)}</h1><div class="muted">${esc(s.n)} · ${esc(s.th || s.sec || '')}</div>${l ? `<div style="font:800 22px Inter;margin-top:6px">${usd(l.c)} <span class="muted" style="font-size:13px;font-weight:600">close ${esc(dfmt(iso(l.d)))}</span></div>` : ''}</div><div style="text-align:center;border:3px solid #00C176;border-radius:18px;padding:10px 18px"><div style="font:800 44px 'Space Grotesk'">${s.ws}<span style="font-size:18px">/10</span></div><div class="muted" style="font-size:12px;font-weight:700">TICKERWISE SCORE</div></div></div>
   <div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px"><div>${[['Momentum', P.m], ['Earnings', P.e], ['Growth', P.g], ['Profitability', P.p], ['Financial Health', P.b]].map(([n, v]) => `<div style="margin:8px 0"><div style="display:flex;justify-content:space-between;font-size:13px;font-weight:600"><span>${n}</span><b>${v != null ? v : '—'}</b></div><div class="r3-bar"><i style="width:${v || 0}%"></i></div></div>`).join('')}</div>
   <div>${svgLine([{ v: z.map(p => p.c), c: '#2F6BFF' }], 120)}<p class="muted" style="margin:2px 0 0;font-size:12px">Past year · range ${usd(mn)}–${usd(mx)} · 1Y ${pct((s.ret || {}).r1y, 0)}</p></div></div>
   <div class="r3-k" style="margin-top:16px"><div><span>Fwd P/E</span><b>${nz((s.val || {}).fpe) && s.val.fpe > 0 ? s.val.fpe.toFixed(0) + 'x' : '—'}</b></div><div><span>Net margin</span><b>${nz((s.mg || {}).net) ? Math.round(s.mg.net) + '%' : '—'}</b></div><div><span>Revenue growth</span><b>${nz(s.rg) ? pct(s.rg, 0) : '—'}</b></div><div><span>Beat rate (8Q)</span><b>${nz(E.l8) ? E.l8 + '%' : '—'}</b></div><div><span>Next earnings</span><b style="font-size:15px">${esc(dfmt(E.next) || '—')}</b></div><div><span>Analysts</span><b style="font-size:15px">${A ? esc(A[7] || '') + (nz(A[0]) ? ' · ' + usd(A[0], 0) : '') : '—'}</b></div></div>
   ${own && own.who.length ? `<p style="margin:14px 0 0;font-size:14px"><b>Famous investors who own it:</b> ${own.who.slice(0, 6).map(m => esc(m.name)).join(', ')}${own.who.length > 6 ? ` and ${own.who.length - 6} more` : ''}.</p>` : ''}
   <p class="muted" style="margin:18px 0 0;font-size:11.5px;border-top:1px solid var(--line);padding-top:10px">Tickerwise · ${esc(location.origin + location.pathname)}#/stock/${esc(t)} · Data as of ${esc(dfmt(TW.asof) || '')}. For education only, not investment advice.</p></div></div></section>`;
  document.title = t + ' One-Page Report — Tickerwise';
}

